#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t old_count = 2;
    size_t new_count = 4;
    int *values = malloc(old_count * sizeof *values);
    if (values == NULL) {
        fputs("initial allocation failed\n", stderr);
        return 1;
    }

    values[0] = 10;
    values[1] = 20;

    int *resized = realloc(values, new_count * sizeof *values);
    if (resized == NULL) {
        fputs("resize failed\n", stderr);
        free(values);
        return 1;
    }
    values = resized;

    for (size_t i = old_count; i < new_count; ++i) {
        values[i] = (int)(i + 1) * 10;
    }
    for (size_t i = 0; i < new_count; ++i) {
        printf("%d%c", values[i], i + 1 == new_count ? '\n' : ' ');
    }

    free(values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int resize_int_array(int **owner, size_t new_count) {
    if (owner == NULL || *owner == NULL || new_count == 0) {
        return 0;
    }
    int *resized = realloc(*owner, new_count * sizeof **owner);
    if (resized == NULL) {
        return 0;
    }
    *owner = resized;
    return 1;
}

int main(void) {
    int *numbers = malloc(2 * sizeof *numbers);
    if (numbers == NULL) return 1;
    numbers[0] = 3;
    numbers[1] = 6;

    if (!resize_int_array(&numbers, 3)) {
        free(numbers);
        return 1;
    }
    numbers[2] = 9;
    printf("%d %d %d\n", numbers[0], numbers[1], numbers[2]);
    free(numbers);
    return 0;
}
